                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 13 != 1 or i == len(rows) - 1:
            kept_rows.append(row)

        if weight == 0:
            state = 5
        else:
            state = (5 * state + weight) % 13

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    aggregated_amounts = collections.defaultdict(int)
    for row in rotated_rows:
        if isinstance(row, list) and len(row) >= 3:
            key = row[0]
            amount = row[1]
            void = row[2]
            if not void and abs(amount) >= 5:
                aggregated_amounts[key] += amount

    result = []
    for key, total in aggregated_amounts.items():
        if total != 0:
            result.append([key, total])

    result.sort()
    return result

